from typing import Iterable


def summarize_words(words: Iterable[str], *, max_words: int = 20) -> str:
    """Return the first `max_words` meaningful words joined with spaces."""

    if max_words <= 0:
        raise ValueError("max_words must be positive")

    cleaned: list[str] = []
    for w in words:
        w = w.strip()
        if not w:
            continue
        cleaned.append(w.lower())
        if len(cleaned) >= max_words:
            break

    return " ".join(cleaned)

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class Money:
    amount: int
    currency: str = "RUB"


def format_money(m: Money) -> str:
    """Format Money as '<amount> <currency>' with basic validation."""

    currency = m.currency.strip()
    if not currency:
        raise ValueError("currency must not be empty")

    return f"{m.amount} {currency}"

import re
from typing import Final


_EMAIL_RE: Final[re.Pattern[str]] = re.compile(
    r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$",
    re.IGNORECASE,
)


def is_valid_email(email: str) -> bool:
    """Validate email with a lightweight regex."""

    if not email:
        return False

    return bool(_EMAIL_RE.fullmatch(email.strip()))

def process_items(items):
    result = []
    for item in items:
        try:
            if item['type'] == 'A':
                result.append(item['value'] * 2)
            else:
                result.append(item['value'] * 3)
        except:
            pass
    return result

